    Regiao(String taxa) {
        this.taxaSeguro = new BigDecimal(taxa);
    }

    public BigDecimal calcularSeguro(BigDecimal subtotalProdutos) {
        return subtotalProdutos.multiply(taxaSeguro).setScale(2, RoundingMode.HALF_EVEN);
    }
}

